SET search_path TO lms, extensions;

-- Add RLS policies for learner_profiles

-- Learner can view their own profile
CREATE POLICY "learner_profiles: read own" ON lms.learner_profiles
  FOR SELECT USING (user_id = auth.uid());

-- Teacher can view assigned learner profiles
CREATE POLICY "learner_profiles: teacher read assigned" ON lms.learner_profiles
  FOR SELECT USING (
    EXISTS (
      SELECT 1 FROM lms.teacher_assignments
      WHERE teacher_id = auth.uid() AND learner_id = learner_profiles.user_id AND is_active = TRUE
    )
  );

-- Admin can view all learner profiles
CREATE POLICY "learner_profiles: admin read all" ON lms.learner_profiles
  FOR SELECT USING (
    EXISTS (SELECT 1 FROM lms.users WHERE id = auth.uid() AND role = 'admin')
  );

-- User can insert their own learner profile (used during signup)
CREATE POLICY "learner_profiles: insert own" ON lms.learner_profiles
  FOR INSERT WITH CHECK (user_id = auth.uid());

-- Learner can update their own profile
CREATE POLICY "learner_profiles: update own" ON lms.learner_profiles
  FOR UPDATE USING (user_id = auth.uid()) WITH CHECK (user_id = auth.uid());

-- Admin can update all learner profiles
CREATE POLICY "learner_profiles: admin update all" ON lms.learner_profiles
  FOR UPDATE USING (
    EXISTS (SELECT 1 FROM lms.users WHERE id = auth.uid() AND role = 'admin')
  ) WITH CHECK (
    EXISTS (SELECT 1 FROM lms.users WHERE id = auth.uid() AND role = 'admin')
  );

-- Admin can insert any learner profile (used when admin creates a user)
CREATE POLICY "learner_profiles: admin insert" ON lms.learner_profiles
  FOR INSERT WITH CHECK (
    EXISTS (SELECT 1 FROM lms.users WHERE id = auth.uid() AND role = 'admin')
  );
